# frozen_string_literal: true

# Generated by BoltFFI. Do not edit.
#
# Builds the Rust crate in `crate/` with cargo, then compiles the extension
# and links the static library of the crate. The install needs cargo and a C
# compiler. Cargo downloads the dependencies that are not in its cache.
#
# The build uses the `release` Cargo profile. Set BOLTFFI_CARGO_PROFILE to
# use another profile, such as `dev` for a debug build. Set CARGO_TARGET_DIR
# to keep the Cargo build for the next install.

require "fileutils"
require "json"
require "mkmf"
require "open3"
require "shellwords"
require "tmpdir"

module BoltFFIExtconf
  ARTIFACT = {{ artifact }}
  EXTENSION = {{ extension }}
  CRATE = File.join(__dir__, "crate")
  CARGO = ENV.fetch("CARGO", "cargo")
  PROFILE = ENV["BOLTFFI_CARGO_PROFILE"].to_s.empty? ? "release" : ENV["BOLTFFI_CARGO_PROFILE"]
  # The rustup toolchain of the generation build, such as `+nightly`.
  TOOLCHAIN_ARGUMENTS = [{{ toolchain_arguments|join(", ") }}].freeze
  # The Cargo feature arguments that BoltFFI generated this extension with.
  # The build uses the same features, so the static library exports every
  # function that the extension calls.
  FEATURE_ARGUMENTS = [{{ feature_arguments|join(", ") }}].freeze
  # The kinds that cargo's `rustc-link-search=[KIND=]PATH` accepts.
  LINK_SEARCH_KINDS = %w[native crate dependency framework all].freeze

  class << self
    def configure
      abort("boltffi: #{EXTENSION} builds only on macOS and Linux") unless darwin? || linux?
      unless File.exist?(File.join(CRATE, "Cargo.toml"))
        abort("boltffi: no crate source in #{CRATE}; run boltffi pack ruby")
      end
      find_executable(CARGO) ||
        abort("boltffi: #{EXTENSION} needs cargo to build; install Rust from https://rustup.rs")

      archive, native_libraries, search_paths = build_crate
      $LOCAL_LIBS << " #{archive.shellescape}"
      search_paths.each do |entry|
        kind, path = entry.split("=", 2)
        kind, path = "all", entry unless path && LINK_SEARCH_KINDS.include?(kind)
        $LDFLAGS << " -L#{path.shellescape}" unless kind == "framework"
        # Only Apple's linker reads -F. GNU ld reads -F as a different option.
        $LDFLAGS << " -F#{path.shellescape}" if %w[framework all].include?(kind) && darwin?
      end
      linked = $LIBS.split
      native = native_libraries.reject { |flag| flag.start_with?("-l") && linked.include?(flag) }
      $LIBS << " #{native.map(&:shellescape).join(" ")}"
      export_only_entry_point
      create_makefile("#{EXTENSION}/#{EXTENSION}")
    end

    # Cargo builds in CARGO_TARGET_DIR when it is set. Otherwise cargo builds
    # in a temporary directory, which goes away before `make` links. rustc
    # puts the static libraries of build scripts into the archive, so the
    # link drops the search paths inside that directory.
    def build_crate
      target_directory = ENV["CARGO_TARGET_DIR"].to_s
      return build_crate_in(File.expand_path(target_directory)) unless target_directory.empty?

      Dir.mktmpdir("boltffi-cargo-") do |directory|
        archive, native_libraries, search_paths = build_crate_in(directory)
        temporary = [directory, File.realpath(directory)]
        search_paths = search_paths.reject do |entry|
          path = entry.split("=", 2).last
          temporary.any? { |prefix| path.start_with?(prefix) }
        end
        [archive, native_libraries, search_paths]
      end
    end

    # The extension keeps a copy of the static library, because `make` links
    # it after this script ends. RubyGems runs `make clean` before `make`, so
    # the copy is a distclean file. RubyGems runs no `make distclean`, so the
    # copy stays in the installed extension directory.
    # Cargo runs in the crate folder, because rustup reads the
    # `rust-toolchain.toml` of the working directory.
    def build_crate_in(target_directory)
      stdout, stderr, status = Open3.capture3(*cargo_command(target_directory), chdir: CRATE)
      abort("boltffi: cargo could not build the #{EXTENSION} crate\n#{stderr}") unless status.success?

      messages = cargo_messages(stdout)
      archive = File.join(Dir.pwd, "lib#{ARTIFACT}.a")
      FileUtils.cp(built_archive(messages), archive)
      $distcleanfiles << File.basename(archive)
      [archive, native_static_libraries(stderr), link_search_paths(messages)]
    end

    def cargo_command(target_directory)
      [
        CARGO, *TOOLCHAIN_ARGUMENTS, "rustc",
        "--manifest-path", File.join(CRATE, "Cargo.toml"),
        "--target-dir", target_directory,
        "--locked", "--profile", PROFILE, "--lib", *FEATURE_ARGUMENTS,
        "--message-format=json-render-diagnostics",
        "--", "--print=native-static-libs"
      ]
    end

    def cargo_messages(stdout)
      stdout.each_line.filter_map do |line|
        JSON.parse(line)
      rescue JSON::ParserError
        nil
      end
    end

    def built_archive(messages)
      messages
        .select { |message| message["reason"] == "compiler-artifact" }
        .flat_map { |message| message["filenames"] }
        .find { |path| File.basename(path) == "lib#{ARTIFACT}.a" } ||
        abort("boltffi: cargo built no lib#{ARTIFACT}.a")
    end

    # The system libraries that the Rust standard library needs.
    def native_static_libraries(stderr)
      line = stderr.each_line
        .map { |text| text.gsub(/\e\[[0-9;]*m/, "") }
        .reverse
        .find { |text| text.include?("native-static-libs:") }
      abort("boltffi: rustc printed no native-static-libs") unless line
      line.split("native-static-libs:", 2).last.split
    end

    # Build scripts add search paths for the native libraries that they link.
    def link_search_paths(messages)
      messages
        .select { |message| message["reason"] == "build-script-executed" }
        .flat_map { |message| message["linked_paths"] }
        .uniq
    end

    def darwin?
      RbConfig::CONFIG["host_os"].include?("darwin")
    end

    def linux?
      RbConfig::CONFIG["host_os"].include?("linux")
    end

    # Ruby loads extensions with RTLD_GLOBAL. Exported Rust symbols could then
    # bind to another extension's copy, so the extension exports only its
    # entry point and, on development Rubies, `ruby_abi_version`.
    def export_only_entry_point
      symbols = ["Init_#{EXTENSION}"]
      symbols << "ruby_abi_version" if have_macro("RUBY_DLN_CHECK_ABI", "ruby.h")
      if darwin?
        symbols.each { |symbol| $DLDFLAGS << " -Wl,-exported_symbol,_#{symbol}" }
      else
        version_script = File.join(Dir.pwd, "#{EXTENSION}.map")
        File.write(version_script, "{ global: #{symbols.join("; ")}; local: *; };\n")
        $DLDFLAGS << " -Wl,--version-script=#{version_script.shellescape}"
      end
    end
  end
end

BoltFFIExtconf.configure
